            hintText: hint,
            prefixIcon: const Icon(Icons.search),
            suffixIcon: searchController.text.isNotEmpty
                ? IconButton(
                    icon: const Icon(Icons.clear),
                    onPressed: () {
                      searchController.clear();
                      onSearchChanged?.call('');
                    },
                    tooltip: 'Clear search',
                  )
                : null,
            filled: true,
            fillColor: scheme.surfaceContainerHighest,
            border: OutlineInputBorder(
              borderRadius: BorderRadius.circular(AppBorderRadius.md),
              borderSide: BorderSide(color: scheme.outlineVariant),
            ),
            enabledBorder: OutlineInputBorder(
              borderRadius: BorderRadius.circular(AppBorderRadius.md),
              borderSide: BorderSide(color: scheme.outlineVariant),
            ),
            focusedBorder: OutlineInputBorder(
              borderRadius: BorderRadius.circular(AppBorderRadius.md),
              borderSide: BorderSide(color: scheme.primary, width: 2),
            ),
            contentPadding: const EdgeInsets.symmetric(
              horizontal: AppSpacing.md,
              vertical: AppSpacing.md,
            ),
          ),
          onChanged: onSearchChanged,
        ),
        // Filter chips
        if (filters.isNotEmpty) ...[
          const SizedBox(height: AppSpacing.sm),
          SingleChildScrollView(
            scrollDirection: Axis.horizontal,
            child: Row(
              children: [
                ...filters.map(
                  (f) => Padding(
                    padding: const EdgeInsets.only(right: AppSpacing.sm),
                    child: FilterChip(
                      label: Text(f.label),
                      selected: selectedFilters.contains(f.key),
                      onSelected: (selected) {
                        final newSet = Set<String>.from(selectedFilters);
                        if (selected) {
                          newSet.add(f.key);
                        } else {
                          newSet.remove(f.key);
                        }
                        onFilterChanged?.call(newSet);
                      },
                      showCheckmark: false,
                      labelStyle: theme.textTheme.labelMedium?.copyWith(
                        color: selectedFilters.contains(f.key)
                            ? scheme.onPrimaryContainer
                            : scheme.onSurfaceVariant,
                      ),
                      backgroundColor: scheme.surfaceContainerHighest,
                      selectedColor: scheme.primaryContainer,
                      checkmarkColor: scheme.onPrimaryContainer,
                      side: BorderSide(
                        color: selectedFilters.contains(f.key)
                            ? scheme.primary
                            : scheme.outlineVariant,
                      ),
                    ),
                  ),
                ),
                if (hasActiveFilters && showFilterCount) ...[
                  const SizedBox(width: AppSpacing.sm),
                  OutlinedButton.icon(
                    onPressed: () {
                      onFilterChanged?.call({});
                    },
                    icon: const Icon(Icons.clear_all, size: 18),
                    label: Text('Clear (${selectedFilters.length})'),
                    style: OutlinedButton.styleFrom(
                      padding: const EdgeInsets.symmetric(
                        horizontal: AppSpacing.md,
                        vertical: AppSpacing.sm,
                      ),
                    ),
                  ),
                ],
              ],
            ),
          ),
        ],
      ],
    );
  }
}

/// Data for a filter chip in the search filter bar.
class FilterChipData {
  const FilterChipData({
    required this.key,
    required this.label,
    this.count,
  });

  final String key;
  final String label;
  final int? count;
}

/// An empty state widget for lists and grids.
///
/// Shows an icon, title, message, and an optional action button.
class EmptyState extends StatelessWidget {
  const EmptyState({
    super.key,
    required this.icon,
    required this.title,
    required this.message,
    this.actionLabel,
    this.onAction,
    this.iconSize = 64,
  });

  final IconData icon;
  final String title;
  final String message;
  final String? actionLabel;
  final VoidCallback? onAction;
  final double iconSize;

  @override
  Widget build(BuildContext context) {
    final theme = Theme.of(context);
    final scheme = theme.colorScheme;

    return Center(
      child: Padding(
        padding: const EdgeInsets.all(AppSpacing.xl),
        child: Column(
          mainAxisSize: MainAxisSize.min,
          children: [
            Icon(
              icon,
              size: iconSize,
              color: scheme.onSurfaceVariant.withValues(alpha: 0.5),
            ),
            const SizedBox(height: AppSpacing.md),
            Text(
              title,
              textAlign: TextAlign.center,
              style: theme.textTheme.headlineSmall?.copyWith(
                color: scheme.onSurface,
                fontWeight: FontWeight.w600,
              ),
            ),
            const SizedBox(height: AppSpacing.sm),
            Text(
              message,
              textAlign: TextAlign.center,
              style: theme.textTheme.bodyMedium?.copyWith(
                color: scheme.onSurfaceVariant,
              ),
            ),
            if (actionLabel != null && onAction != null) ...[
              const SizedBox(height: AppSpacing.lg),
              AppButton(
                label: actionLabel!,
                variant: AppButtonVariant.primary,
                onPressed: onAction,
              ),
            ],
          ],
        ),
      ),
    );
  }
}

/// A loading overlay that can wrap any content.
///
/// Shows a semi-transparent backdrop with a spinner and optional message.
/// Use instead of raw Stack + CircularProgressIndicator for consistency.
class LoadingOverlay extends StatelessWidget {
  const LoadingOverlay({
    super.key,
    required this.isLoading,
    required this.child,
    this.message,
  });

  final bool isLoading;
  final Widget child;
  final String? message;

  @override
  Widget build(BuildContext context) {
    final theme = Theme.of(context);
    final scheme = theme.colorScheme;

    return Stack(
      children: [
        child,
        if (isLoading)
          Positioned.fill(
            child: Material(
              color: scheme.surface.withValues(alpha: 0.7),
              child: Center(
                child: Container(
                  padding: const EdgeInsets.all(AppSpacing.xl),
                  decoration: BoxDecoration(
                    color: scheme.surfaceContainer,
                    borderRadius: BorderRadius.circular(AppBorderRadius.lg),
                    boxShadow: [
                      BoxShadow(
                        color: AppColors.shadow,
                        blurRadius: AppElevation.level3,
                        offset: const Offset(0, 4),
                      ),
                    ],
                  ),
                  child: Column(
                    mainAxisSize: MainAxisSize.min,
                    children: [
                      CircularProgressIndicator(
                        valueColor: AlwaysStoppedAnimation<Color>(scheme.primary),
                      ),
                      if (message != null) ...[
                        const SizedBox(height: AppSpacing.md),
                        Text(
                          message!,
                          style: theme.textTheme.bodyMedium?.copyWith(
                            color: scheme.onSurfaceVariant,
                          ),
                        ),
                      ],
                    ],
                  ),
                ),
              ),
            ),
          ),
      ],
    );
  }
}

/// A paginated data table with sorting and selection.
///
/// Generic over the row type T. The caller provides columns, a sort function,
/// and a selection handler. This keeps the table purely presentational.
class DataTableView<T> extends StatefulWidget {
  const DataTableView({
    super.key,
    required this.columns,
    required this.rows,
    this.sortColumnIndex,
    this.sortAscending = true,
    this.onSort,
    this.selectedRows = const {},
    this.onSelectionChanged,
    this.rowHeight = 56,
    this.headingRowHeight = 56,
    this.showCheckboxColumn = true,
    this.onRowTap,
    this.emptyState,
  });

  final List<DataColumn> columns;
  final List<T> rows;
  final int? sortColumnIndex;
  final bool sortAscending;
  final Function(int, bool)? onSort;
  final Set<int> selectedRows;
  final ValueChanged<Set<int>>? onSelectionChanged;
  final double rowHeight;
  final double headingRowHeight;
  final bool showCheckboxColumn;
  final void Function(T row)? onRowTap;
  final Widget? emptyState;

  @override
  State<DataTableView<T>> createState() => _DataTableViewState<T>();
}

class _DataTableViewState<T> extends State<DataTableView<T>> {
  @override
  Widget build(BuildContext context) {
    if (widget.rows.isEmpty) {
      return widget.emptyState ??
          const EmptyState(
            icon: Icons.inbox_outlined,
            title: 'No data',
            message: 'There are no items to display.',
          );
    }

    return LayoutBuilder(
      builder: (context, constraints) {
        return SingleChildScrollView(
          scrollDirection: Axis.horizontal,
          child: ConstrainedBox(
            constraints: BoxConstraints(minWidth: constraints.maxWidth),
            child: DataTable(
              headingRowHeight: widget.headingRowHeight,
              dataRowMinHeight: widget.rowHeight,
              dataRowMaxHeight: widget.rowHeight,
              sortColumnIndex: widget.sortColumnIndex,
              sortAscending: widget.sortAscending,
              onSelectAll: widget.onSelectionChanged != null
                  ? (selected) {
                      final newSet = selected == true ? Set<int>.from(Iterable.generate(widget.rows.length))
                          : <int>{};
                      widget.onSelectionChanged!(newSet);
                    }
                  : null,
              columns: [
                if (widget.showCheckboxColumn)
                  DataColumn(
                    label: const SizedBox.shrink(),
                    numeric: false,
                    tooltip: 'Select row',
                  ),
                ...widget.columns,
              ],
              rows: List.generate(widget.rows.length, (index) {
                final row = widget.rows[index];
                final selected = widget.selectedRows.contains(index);
                return DataRow(
                  selected: selected,
                  onSelectChanged: widget.onSelectionChanged != null
                      ? (selected) {
                          final newSet = Set<int>.from(widget.selectedRows);
                          if (selected == true) {
                            newSet.add(index);
                          } else {
                            newSet.remove(index);
                          }
                          widget.onSelectionChanged!(newSet);
                        }
                      : null,
                  onLongPress: widget.onRowTap != null ? () => widget.onRowTap!(row) : null,
