/// A simple avatar with initials fallback.
///
/// Uses the app's colour tokens for the background so it works in both themes.
class AppAvatar extends StatelessWidget {
  const AppAvatar({
    super.key,
    this.imageUrl,
    this.name,
    this.radius = 20,
    this.backgroundColor,
    this.textStyle,
  });

  final String? imageUrl;
  final String? name;
  final double radius;
  final Color? backgroundColor;
  final TextStyle? textStyle;

  @override
  Widget build(BuildContext context) {
    final theme = Theme.of(context);
    final scheme = theme.colorScheme;

    final bg = backgroundColor ??
        (name != null
            ? _colorFromString(name!, scheme)
            : scheme.primaryContainer);

    return CircleAvatar(
      radius: radius,
      backgroundColor: bg,
      backgroundImage: imageUrl != null ? NetworkImage(imageUrl!) : null,
      child: imageUrl == null && name != null
          ? Text(
              _initials(name!),
              style: textStyle ??
                  theme.textTheme.titleMedium?.copyWith(
                    color: scheme.onPrimaryContainer,
                    fontWeight: FontWeight.w600,
                  ),
            )
          : null,
    );
  }

  String _initials(String name) {
    final parts = name.trim().split(RegExp(r'\s+'));
    if (parts.length == 1) return parts[0].substring(0, 1).toUpperCase();
    return '${parts.first.substring(0, 1)}${parts.last.substring(0, 1)}'.toUpperCase();
  }

  Color _colorFromString(String str, ColorScheme scheme) {
    // Simple hash to pick a consistent colour from the palette
    final hash = str.codeUnits.fold(0, (a, b) => a + b);
    final colors = [
      scheme.primaryContainer,
      scheme.secondaryContainer,
      scheme.tertiaryContainer,
      AppColors.successContainer,
      AppColors.warningContainer,
      AppColors.infoContainer,
    ];
    return colors[hash % colors.length];
  }
}